import numpy as np
import pandas as pd


def generate_signals(df):
    close = df["close"]
    change = close.diff().dropna()
    gain = np.maximum(change, 0)
    loss = np.maximum(-change, 0)
    avg_gain = gain.rolling(16).mean()
    avg_loss = loss.rolling(16).mean()
    rsi = 100 - 100 / (1 + avg_gain / avg_loss)
    rsi = rsi.fillna(50)

    pos = np.zeros(len(rsi), dtype=int)
    state = 0
    entry = 0.0
    for t in range(len(rsi)):
        if state == 0:
            if rsi[t] < 28:
                state, entry = 1, rsi[t]
            elif rsi[t] > 72:
                state, entry = -1, rsi[t]
        elif state == 1:
            if rsi[t] > 52:
                state = 0
        elif state == -1:
            if rsi[t] < 52:
                state = 0
        pos[t] = state
    return pd.Series(pos, index=df.index)
