    high = df["high"]
    low = df["low"]
    prior_high = high.rolling(60).max().shift(1).to_numpy()
    prior_low = low.rolling(60).min().shift(1).to_numpy()

    pos = np.zeros(len(close), dtype=int)
    for t in range(len(close)):
        if t < 60:
            pos[t] = 0
        elif close[t] > prior_high[t]:
            pos[t] = 1
        elif close[t] < prior_low[t]:
            pos[t] = 0
        else:
            pos[t] = pos[t - 1]
    return pd.Series(pos, index=df.index)
